        return count

    def count_strings_greater_equal(limit):
        count = 0
        for i in range(k):
            if limit[i] > 'a':
                count += (ord(limit[i]) - ord('a')) * (26 ** (k - i - 1))
                break
            count += (ord('z') - ord(limit[i]) + 1) * (26 ** (k - i - 1))
        return count

    total_strings = count_strings_less_equal(t) - count_strings_greater_equal(s) + 1
    median_position = (total_strings + 1) // 2

